"use strict";(globalThis.webpackChunkall_maker=globalThis.webpackChunkall_maker||[]).push([[5746],{7185(e,n,t){t.r(n),t.d(n,{assets:()=>l,contentTitle:()=>r,default:()=>c,frontMatter:()=>s,metadata:()=>i,toc:()=>d});const i=JSON.parse('{"id":"metalworking/welding/viking-helmet","title":"Viking helmet","description":"So, funny story.","source":"@site/docs/metalworking/welding/viking-helmet.md","sourceDirName":"metalworking/welding","slug":"/metalworking/welding/viking-helmet","permalink":"/docs/metalworking/welding/viking-helmet","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":4,"frontMatter":{"sidebar_position":4,"title":"Viking helmet","sidebar_label":"Viking helmet"},"sidebar":"projectsSidebar","previous":{"title":"Welding table","permalink":"/docs/metalworking/welding/welding-table"},"next":{"title":"Soldered lamp","permalink":"/docs/metalworking/welding/solder-lamp"}}');var a=t(4848),o=t(8453);const s={sidebar_position:4,title:"Viking helmet",sidebar_label:"Viking helmet"},r=void 0,l={},d=[{value:"Idea",id:"idea",level:2},{value:"Challenge",id:"challenge",level:2},{value:"Outcome",id:"outcome",level:2},{value:"Learnings",id:"learnings",level:2}];function h(e){const n={a:"a",em:"em",h2:"h2",li:"li",ol:"ol",p:"p",...(0,o.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(n.p,{children:"So, funny story."}),"\n",(0,a.jsx)(n.p,{children:"Back in Belgrade, in another time, there were these hipster dudes who created a movement around growing, styling, and promoting long beards and mustaches. They posted a lot on social media, but mostly some funny beard memes and handsome male models who grew out their beards. It was a whole thing for a couple of years, they even held some beardness competitions, I heard."}),"\n",(0,a.jsx)(n.p,{children:"Anyway, my friend Jovana and I saw that they were hosting a viking night! The promise was viking music, ambiance, food, and barrels of fine-quality mead! Or failing that at least heaps of rakija!\nJovana is an accomplished artist\u2014painter and a sculptor. She graduated from the School of applied arts with a degree in sculpting metal. Or something such, I am not well-versed in the ways of actual art."}),"\n",(0,a.jsxs)(n.p,{children:["But, as you can imagine, she uses MIG, TIG, oxy-acetylene welding, and is a flat-out blacksmith. Check out her ",(0,a.jsx)(n.a,{href:"https://www.instagram.com/jovana_tucovic/?hl=en",children:"Instagram profile"}),"."]}),"\n",(0,a.jsx)(n.p,{children:"She's also a viking enthusiast! So we thought\u2014you know what would be funny? If we made viking helmets for the Viking night and dressed up and then let's go get hammered with a bunch of hulking, sexy, bearded dudes. :)"}),"\n",(0,a.jsx)(n.h2,{id:"idea",children:"Idea"}),"\n",(0,a.jsx)(n.p,{children:"The plan was not to be historically accurate, but dress up, completely over the top, and forge horned helmets like those cartoonish depictions of demonic viking figures conquering the new world."}),"\n",(0,a.jsx)(n.p,{children:"We were alerady hanging out in her forge so we split the work\u2014Jovana would make the helmets out of steel sheets and I would make the horns out of wood as we did not have any actual animal horns."}),"\n",(0,a.jsx)(n.h2,{id:"challenge",children:"Challenge"}),"\n",(0,a.jsx)(n.p,{children:"Multiple things. Jovana had to:"}),"\n",(0,a.jsxs)(n.ol,{children:["\n",(0,a.jsx)(n.li,{children:"Measure our beautiful skulls and tailor the steel to the shape."}),"\n",(0,a.jsx)(n.li,{children:"Decorate the helmets somehow so they look somewhat realistic."}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"I had to:"}),"\n",(0,a.jsxs)(n.ol,{children:["\n",(0,a.jsx)(n.li,{children:"Find some wood that could look like bone."}),"\n",(0,a.jsx)(n.li,{children:"Carve out 4 horn-looking pieces and attach them somehow."}),"\n"]}),"\n",(0,a.jsx)(n.h2,{id:"outcome",children:"Outcome"}),"\n",(0,a.jsx)(n.p,{children:"Up to that point, Jovana had had a lot of practice tailoring steel to body shapes. She used the blow torch to heat up the metal sheets and hammered them into a battle-hewn look. She then welded on the lower part, cut the edge and curled it to decorate it. It was a simple technique but it covered the weld marks, gave it a worn out look, and added to the structural integrity."}),"\n",(0,a.jsx)(n.p,{children:"As for me, she gave an discarded picture frame to destroy. It was not very big, so I had to plan where to cut so I end up with 4 similar pieces. The trick was to keep a corner in every piece so I could fashion them into a curved figure."}),"\n",(0,a.jsx)(n.p,{children:"It took some angle grinder work and a lot of hand-filing, but I ended up with something pointier than previously and it did curve inwards."}),"\n",(0,a.jsx)(n.p,{children:"We drilled the holes in the helmets, used self-drilling screws to attach the wood from the inside and\u2014voila!"}),"\n",(0,a.jsx)("img",{src:"/img/metalworking/welding/vikinghelmet.jpg",alt:"Viking",style:{maxWidth:"400px",width:"100%"}}),"\n",(0,a.jsx)(n.p,{children:"This of course was not enough for the viking night! We dressed up\u2014Jovana found a traditional dress with viking motifs and I wore a kilt and a tunic. We were ready to drink with the gods!"}),"\n",(0,a.jsx)(n.h2,{id:"learnings",children:"Learnings"}),"\n",(0,a.jsx)(n.p,{children:"Expecting mead, wild boar, and Wardruna playing in the background we charged into a cafe in downtown Belgrade where the event was held. To our disappointment, we were welcomed by pop music and some hipster dudes in skinny jeans and wax on their mustaches."}),"\n",(0,a.jsxs)(n.p,{children:["There was no mead, but instead cocktails with ",(0,a.jsx)(n.a,{href:"https://belgrade.tips/index.php/2021/11/09/medovaca-the-secret-of-honey-brandy-and-why-everyone-loves-it/",children:"medova\u010da"}),". There were no wild boars, swords, or painted faces\u2014certainly no kilts. It's a bit weird to be the only dude in a skirt in the middle of a culture where that is not a thing."]}),"\n",(0,a.jsx)(n.p,{children:"So we had a couple of beers and moved on with our lives."}),"\n",(0,a.jsxs)(n.p,{children:["As for the learnings, there weren't really any maker-specific ones. We had fun listening to the music we both liked making something together. And ",(0,a.jsx)(n.em,{children:"making up"})," stuff together obviously since we totally misunderstood the Instagram invite. Or they lied."]}),"\n",(0,a.jsx)(n.p,{children:"If there are any learnings, it'd be this\u2014do not expect hardcore viking, historical-reenactment events from a bunch of hipster beard enthusiasts. ;)"})]})}function c(e={}){const{wrapper:n}={...(0,o.R)(),...e.components};return n?(0,a.jsx)(n,{...e,children:(0,a.jsx)(h,{...e})}):h(e)}},8453(e,n,t){t.d(n,{R:()=>s,x:()=>r});var i=t(6540);const a={},o=i.createContext(a);function s(e){const n=i.useContext(o);return i.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function r(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:s(e.components),i.createElement(o.Provider,{value:n},e.children)}}}]);